import{_ as n,o as t,c as r,ag as a}from"./chunks/framework.CrXGS008.js";const h=JSON.parse('{"title":"Frameworks und Ressourcen","description":"","frontmatter":{},"headers":[],"relativePath":"de/bridge/index.md","filePath":"de/bridge/index.md"}'),o={name:"de/bridge/index.md"};function d(s,e,i,c,l,u){return t(),r("div",null,[...e[0]||(e[0]=[a(`<h1 id="frameworks-und-ressourcen" tabindex="-1">Frameworks und Ressourcen <a class="header-anchor" href="#frameworks-und-ressourcen" aria-label="Permalink to &quot;Frameworks und Ressourcen&quot;">​</a></h1><p>Jedes Nayretis Skript spricht über die Bridge von <code>nay_lib</code> mit deinem Server. Sie erkennt dein Framework, Inventar, Target und deine Benachrichtigungen bei der ersten Nutzung, sodass dasselbe Skript auf jedem unterstützten Stack läuft.</p><h2 id="unterstutzte-stacks" tabindex="-1">Unterstützte Stacks <a class="header-anchor" href="#unterstutzte-stacks" aria-label="Permalink to &quot;Unterstützte Stacks&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Modul</th><th>Adapter</th><th>Ausweichlösung</th></tr></thead><tbody><tr><td>Framework</td><td><code>qbox</code> (qbx_core), <code>ox</code> (ox_core), <code>esx</code> (es_extended), <code>qbcore</code> (qb-core), <code>custom</code></td><td>keine, das Skript stoppt mit einem Fehler</td></tr><tr><td>Inventar</td><td><code>ox_inventory</code>, <code>qs-inventory</code>, <code>qb-inventory</code></td><td><code>framework</code> (das eigene Inventar des Frameworks)</td></tr><tr><td>Target</td><td><code>ox_target</code>, <code>qb-target</code></td><td><code>none</code> (Tastenhinweise)</td></tr><tr><td>Benachrichtigungen</td><td><code>ox_lib</code>, <code>nayretis</code> (nur wenn erzwungen)</td><td><code>framework</code>, dann <code>native</code> (GTA-Feed)</td></tr></tbody></table><p>Die Erkennung folgt der Reihenfolge der Tabelle. Starte <code>nay_lib</code> <strong>nach</strong> deinen Framework-, Inventar- und Target-Ressourcen, sonst können sie nicht erkannt werden.</p><h2 id="einen-adapter-erzwingen" tabindex="-1">Einen Adapter erzwingen <a class="header-anchor" href="#einen-adapter-erzwingen" aria-label="Permalink to &quot;Einen Adapter erzwingen&quot;">​</a></h2><p>Wählt die Erkennung die falsche Ressource, erzwinge sie in der <code>server.cfg</code> mit <code>setr</code> (auch der Client liest den Wert):</p><div class="language-cfg vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cfg</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>setr nay:framework &quot;esx&quot;</span></span>
<span class="line"><span>setr nay:inventory &quot;ox_inventory&quot;</span></span>
<span class="line"><span>setr nay:target &quot;ox_target&quot;</span></span>
<span class="line"><span>setr nay:notify &quot;native&quot;</span></span></code></pre></div><p>Die Werte sind die oben genannten Adapternamen oder <code>auto</code> (der Standard). Siehe <a href="/de/nay-lib/convars">Convars</a>.</p><p>Dein Framework steht nicht in der Liste? Schreibe einen <a href="/de/bridge/custom">eigenen Adapter</a>.</p><h2 id="bekannte-einschrankungen" tabindex="-1">Bekannte Einschränkungen <a class="header-anchor" href="#bekannte-einschrankungen" aria-label="Permalink to &quot;Bekannte Einschränkungen&quot;">​</a></h2><ul><li><strong>ox_core</strong>: Es gibt kein Dienst-Flag, daher gilt die aktive Gruppe als Job im Dienst. Der höchste Rang einer Gruppe zählt als Chef.</li><li><strong>ox_inventory</strong> (mit jedem Framework): Benutzbare Items müssen in <code>ox_inventory/data/items.lua</code> existieren. ox_inventory ruft den Item-Callback nur für Items ohne <code>consume</code>, <code>client.export</code> oder <code>server.export</code> auf.</li><li><strong>qb-inventory</strong>: Item-Metadaten werden beim Zählen von Items ignoriert.</li><li><strong>qs-inventory</strong>: Die Rückgabewerte beim Hinzufügen und Entfernen von Items sind nicht dokumentiert. Jedes Ergebnis außer <code>false</code> gilt als Erfolg.</li><li><strong>ESX</strong>: Benachrichtigungen nutzen <code>esx_notify</code>, wenn es gestartet ist, sonst den GTA-Feed.</li></ul>`,12)])])}const p=n(o,[["render",d]]);export{h as __pageData,p as default};
